          <p class="text-slate-600 text-sm">Save, preview on desktop and mobile, run the LINK check before sharing.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      true,
      5,
      NOW(),
      NOW()
    )
    RETURNING id INTO v_lesson_id;
    
